    private static let json = #"""
[
{"name":"get_boards","description":"List boards (tabs, including closed ones: 'closed': true) with columns and cards (notes are Markdown; agents = assignees). The last column of a board is its 'done' column. Optional search/filter like the app's. Card order = priority order.","inputSchema":{"type":"object","properties":{"board":{"type":"string","description":"board name or id (default: the tab on screen)"},"query":{"type":"string"},"priority":{"enum":["low","medium","high"],"type":"string"},"tag":{"type":"string"},"agent":{"type":"string","description":"only cards assigned to this agent (name or model, e.g. 'claude', 'me', 'opus')"}}}},
{"name":"add_card","description":"Add a card (default: first column of the tab on screen). notes accept Markdown (headings, lists, - [ ] tasks, **bold**, `code`, code blocks, links), rendered in the app's card panel.","inputSchema":{"type":"object","properties":{"title":{"type":"string"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"},"position":{"type":"integer","description":"1-based rank within its column; 1 = do first. Default: last."},"notes":{"type":"string"},"priority":{"enum":["low","medium","high"],"type":"string"},"due":{"type":"string","description":"ISO date, '' to clear"},"tags":{"items":{"type":"string"},"type":"array"},"agents":{"items":{"anyOf":[{"type":"string"},{"properties":{"name":{"type":"string"},"model":{"type":"string"},"effort":{"type":"string"}},"required":["name"],"type":"object"}]},"type":"array","description":"Who is assigned: any number of agents, each {name, model?, effort?}. name = an AI (claude, codex, chatgpt, gemini, copilot, cursor, windsurf, mistral, deepseek, grok, perplexity, llama, qwen, kimi, zed, cline, aider, opencode, goose, or any other name) or 'me' for the user. model = free text (e.g. 'Opus 5.5', 'GPT-6.2 Sol', 'Gemini 4 Carbon'). effort = minimal | low | medium | high | xhigh | max (Claude and OpenAI: low..max; Gemini: minimal..xhigh; free text accepted). Replaces the whole list; [] clears it. A plain string means just the name."},"column":{"type":"string","description":"column name or id"}},"required":["title"]}},
{"name":"reorder_cards","description":"Set the priority order of cards in a column: card_ids go first, in that order (position 1 = do first); other cards follow. Cards are listed by get_boards in this order.","inputSchema":{"type":"object","properties":{"column":{"type":"string"},"card_ids":{"items":{"type":"string"},"type":"array"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"}},"required":["column","card_ids"]}},
{"name":"update_card","description":"Edit a card; 'column' moves it within its board, 'to_board' moves it to another board (or phase).","inputSchema":{"type":"object","properties":{"card_id":{"type":"string"},"to_board":{"type":"string","description":"board name or id (default: the tab on screen)"},"position":{"type":"integer","description":"1-based rank within its column; 1 = do first. Default: last."},"title":{"type":"string"},"notes":{"type":"string"},"priority":{"enum":["low","medium","high"],"type":"string"},"due":{"type":"string","description":"ISO date, '' to clear"},"tags":{"items":{"type":"string"},"type":"array"},"agents":{"items":{"anyOf":[{"type":"string"},{"properties":{"name":{"type":"string"},"model":{"type":"string"},"effort":{"type":"string"}},"required":["name"],"type":"object"}]},"type":"array","description":"Who is assigned: any number of agents, each {name, model?, effort?}. name = an AI (claude, codex, chatgpt, gemini, copilot, cursor, windsurf, mistral, deepseek, grok, perplexity, llama, qwen, kimi, zed, cline, aider, opencode, goose, or any other name) or 'me' for the user. model = free text (e.g. 'Opus 5.5', 'GPT-6.2 Sol', 'Gemini 4 Carbon'). effort = minimal | low | medium | high | xhigh | max (Claude and OpenAI: low..max; Gemini: minimal..xhigh; free text accepted). Replaces the whole list; [] clears it. A plain string means just the name."},"column":{"type":"string","description":"column name or id"}},"required":["card_id"]}},
{"name":"delete_card","description":"Delete a card.","inputSchema":{"type":"object","properties":{"card_id":{"type":"string"}},"required":["card_id"]}},
{"name":"clear_last_column","description":"Delete every card of the board's last ('done') column — the app's trash button.","inputSchema":{"type":"object","properties":{"board":{"type":"string","description":"board name or id (default: the tab on screen)"}}}},
{"name":"add_column","description":"Add a column at the end.","inputSchema":{"type":"object","properties":{"name":{"type":"string"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"},"color":{"enum":["gray","blue","green","orange","purple","pink","teal","red"],"type":"string"}},"required":["name"]}},
{"name":"update_column","description":"Rename and/or recolor a column.","inputSchema":{"type":"object","properties":{"column":{"type":"string"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"},"name":{"type":"string"},"color":{"enum":["gray","blue","green","orange","purple","pink","teal","red"],"type":"string"}},"required":["column"]}},
{"name":"delete_column","description":"Delete a column; its cards move to the left neighbour. Not the last column.","inputSchema":{"type":"object","properties":{"column":{"type":"string"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"}},"required":["column"]}},
{"name":"add_board","description":"Create a board (tab) and switch to it. With parent (a top-level board's id or name) it becomes a phase (sub-board) of that board, with the parent's columns by default. Optional columns (names) and starter cards (same fields as add_card) — use it to recreate any template.","inputSchema":{"type":"object","properties":{"name":{"type":"string"},"parent":{"type":"string","description":"board name or id (default: the tab on screen)"},"columns":{"items":{"type":"string"},"type":"array"},"cards":{"items":{"properties":{"title":{"type":"string"},"notes":{"type":"string"},"priority":{"enum":["low","medium","high"],"type":"string"},"due":{"type":"string"},"tags":{"items":{"type":"string"},"type":"array"},"agents":{"items":{"anyOf":[{"type":"string"},{"properties":{"name":{"type":"string"},"model":{"type":"string"},"effort":{"type":"string"}},"required":["name"],"type":"object"}]},"type":"array"},"column":{"type":"string"},"position":{"type":"integer"}},"required":["title"],"type":"object"},"type":"array"}},"required":["name"]}},
{"name":"update_board","description":"Rename a board and/or close it (closed=true: hides the tab, nothing is deleted, it stays in the app's Projets menu) or reopen it (closed=false).","inputSchema":{"type":"object","properties":{"board":{"type":"string"},"name":{"type":"string"},"closed":{"type":"boolean"}},"required":["board"]}},
{"name":"select_board","description":"Switch the app to this tab (reopens it if it was closed).","inputSchema":{"type":"object","properties":{"board":{"type":"string"}},"required":["board"]}},
{"name":"set_filter","description":"Filter what the app shows on the current tab, like the user's search field and filter button: any of priority, tag, agent (e.g. 'claude', 'me', or part of a model name) and query (text in title, notes, tags, agents). Replaces the current filter; call it with no argument to clear it. Applied immediately and only on screen (nothing is saved): it is dropped when the tab changes or the app restarts. get_boards (with the same fields) only reads, it does not change the screen.","inputSchema":{"type":"object","properties":{"priority":{"enum":["low","medium","high"],"type":"string"},"tag":{"type":"string"},"agent":{"type":"string"},"query":{"type":"string"}}}},
{"name":"delete_board","description":"Close a board (tab) or phase and delete its cards (a board's phases go with it). Deleting the last one shows the app's welcome page.","inputSchema":{"type":"object","properties":{"board":{"type":"string"}},"required":["board"]}},
{"name":"export_board","description":"Export a board to a file: json (app's share format, re-importable, default), csv (one row per card, opens in Excel) or markdown.","inputSchema":{"type":"object","properties":{"path":{"type":"string"},"board":{"type":"string","description":"board name or id (default: the tab on screen)"},"format":{"enum":["json","csv","markdown"],"type":"string"},"overwrite":{"type":"boolean"}},"required":["path"]}},
{"name":"import_board","description":"Import a board from a JSON file exported by the app or export_board, as a new tab.","inputSchema":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}}
]
"""#
